","import React from "react";
import { Card } from "@servicenow/react-components/Card";
import "./app.css";

const STEPS = [
 {
 n: 1,
 title: "Create the application scope",
 body: "In ServiceNow Studio, create a new scoped application named Forecast Variance."
 },
 {
 n: 2,
 title: "Create the table",
 body: "Create a table to hold forecast variance records for the exercise."
 },
 {
 n: 3,
 title: "Add fields",
 body: "Add the fields required to capture forecast and actual values."
 }
];

export default function App() {
 return (
 <div className="lab">
 <h1 className="lab-title">Lab Exercise: Fundamentals</h1>
 <p className="lab-meta">Beginner &middot; 30 minutes</p>

 {STEPS.map(step => (
 <Card key={step.n}>
 <div className="lab-step">
 <h2 className="lab-step-title">
 Step {step.n}: {step.title}
 </h2>
 <p className="lab-step-body">{step.body}</p>
 </div>
 </Card>
 ))}
 </div>
 );
}
